import { GoogleGenAI, ThinkingLevel } from "@google/genai";
import { z } from "zod/v4";
import { NextRequest, NextResponse } from "next/server";

const MODEL = "gemma-4-26b-a4b-it";

const BoxSchema = z.object({
  box_2d: z.tuple([z.number(), z.number(), z.number(), z.number()]),
  label: z.string(),
});
const BoxesSchema = z.array(BoxSchema);

export async function POST(req: NextRequest) {
  const formData = await req.formData();
  const file = formData.get("image") as File | null;
  const object = formData.get("object") as string | null;

  if (!file || !object) {
    return NextResponse.json(
      { error: "Missing image or object parameter" },
      { status: 400 },
    );
  }

  const buffer = Buffer.from(await file.arrayBuffer());
  const base64 = buffer.toString("base64");
  const mimeType = file.type || "image/png";
  const prompt = `Detect all ${object} in the image.`;

  const ai = new GoogleGenAI({ apiKey: process.env["GEMINI_API_KEY"] });

  const response = await ai.models.generateContent({
    model: MODEL,
    config: {
      temperature: 1,
      thinkingConfig: {
        thinkingLevel: ThinkingLevel.HIGH,
        includeThoughts: true,
      },
    },
    contents: [
      {
        role: "user",
        parts: [
          { text: prompt },
          { inlineData: { data: base64, mimeType } },
        ],
      },
    ],
  });

  const text = response.text ?? "";

  const jsonMatch = text.match(/\[\s*\{[\s\S]*?\}\s*\]/);
  if (!jsonMatch) {
    return NextResponse.json(
      { error: "No bounding boxes found in model response", raw: text },
      { status: 422 },
    );
  }

  const parsed = JSON.parse(jsonMatch[0]);
  const boxes = BoxesSchema.parse(parsed);

  return NextResponse.json({ boxes });
}
